    /// ```
    ///
    /// ```js,expect_diagnostic
    /// window.setTimeout("alert('Hi!');", 100);
    /// ```
    ///
    /// ### Valid
    ///
    /// ```js
    /// setTimeout(function () {
    ///     alert("Hi!");
    /// }, 100);
    /// ```
    ///
    /// ```js
    /// setInterval(() => {
    ///     alert("Hi!");
    /// }, 100);
    /// ```
    ///
    pub NoImpliedEval {
        version: "next",
        name: "noImpliedEval",
        language: "js",
        recommended: false,
        severity: Severity::Error,
    }
