impl Rule for NoImpliedEval {
    type Query = Semantic<JsCallExpression>;
    type State = ();
    type Signals = Option<Self::State>;
    type Options = NoImpliedEvalOptions;

    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
        let call = ctx.query();
        let model = ctx.model();

        let callee = call.callee().ok()?.omit_parentheses();
        let (reference, name) = global_identifier(&callee)?;

        if !matches!(
            name.text(),
            "setTimeout" | "setInterval" | "setImmediate"
        ) {
            return None;
        }

        // Skip when the function name is shadowed by a local binding.
        if model.binding(&reference).is_some() {
            return None;
        }

        let arguments = call.arguments().ok()?;
        let first_argument = arguments.args().into_iter().next()?.ok()?;
        let first_expression = first_argument.as_any_js_expression()?;

        is_string_like(first_expression).then_some(())
    }

    fn diagnostic(ctx: &RuleContext<Self>, _: &Self::State) -> Option<RuleDiagnostic> {
        let node = ctx.query();
        Some(
            RuleDiagnostic::new(
                rule_category!(),
                node.range(),
                markup! {
                    "Implied eval() is not allowed."
                },
            )
            .note(markup! {
                "Passing strings to functions like setTimeout, setInterval, or setImmediate is a form of implied eval() and can lead to security and performance issues."
            })
            .note(markup! {
                "Use a function instead of a string."
            }),
        )
    }
