/// Returns `true` if `expr` evaluates to a string in a way that would be treated
/// as code by an implied `eval()`, that is:
///
/// - a string literal,
/// - a template literal without any substitution,
/// - a `+` binary expression where at least one operand is string-like.
///
/// Any surrounding parentheses are ignored.
fn is_string_like(expr: &AnyJsExpression) -> bool {
    let expr = expr.clone().omit_parentheses();
    match expr {
        AnyJsExpression::AnyJsLiteralExpression(literal) => {
            literal.as_js_string_literal_expression().is_some()
        }
        AnyJsExpression::JsTemplateExpression(template) => {
            template.tag().is_none()
                && template
                    .elements()
                    .into_iter()
                    .all(|element| element.as_js_template_element().is_none())
        }
        AnyJsExpression::JsBinaryExpression(binary) => {
            if binary.operator().ok() != Some(JsBinaryOperator::Plus) {
                return false;
            }
            binary.left().is_ok_and(|left| is_string_like(&left))
                || binary.right().is_ok_and(|right| is_string_like(&right))
        }
        _ => false,
    }
}
